from pypdf import PdfReader
from pathlib import Path
keywords = ['OAT','PCET','proton','pH','low-coordin','coordination','ClO2','chlorine dioxide','Co(IV)','Co(iv)','cobalt(IV)','vacanc','oxygen atom transfer','proton-coupled electron transfer']
pdfs = {
    '2023_EST': Path('assets/uploads/7ed830e3_（相关度高）2023-EST-Co3O4-OAT during Co(IV) in the Co3O4 chlorite process&PCET in Co(IV)mediated ClO2 generation-pH对Cl形态影响.pdf'),
    '2024_PNAS_SI': Path('assets/uploads/3c972c4c_【SI】2024-PNAS-UV-induced-OV-Co3O4- OV-induced low coordinated Co& anchor Cl to produce 三Co(IV)=O👉ClO2.pdf')
}
for name, path in pdfs.items():
    print('\n'+'='*20, name, '='*20)
    reader = PdfReader(str(path))
    for i, page in enumerate(reader.pages):
        try:
            text = page.extract_text() or ''
        except Exception as e:
            text = ''
        low = text.lower()
        hits = [k for k in keywords if k.lower() in low]
        if hits:
            print(f'Page {i+1}: hits={hits[:8]}')
            snippet = ' '.join(text.split())
            # print first 600 chars
            print(snippet[:800])
            print('---')
